{
  "findings": [
    {
      "check_id": "CKV_AWS_23",
      "title": "Security group ingress allows all traffic from 0.0.0.0/0",
      "resource": "aws_security_group.lb",
      "severity": "HIGH",
      "explanation": "The ingress rule allows all protocols and ports (protocol = -1, port range 0-0) from any IP address (0.0.0.0/0), which exposes the load balancer to unrestricted network access."
    },
    {
      "check_id": "CKV_AWS_24",
      "title": "Security group egress allows all traffic to 0.0.0.0/0",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The egress rule allows all outbound traffic to any destination, which can facilitate data exfiltration or lateral movement if the instance is compromised."
    }
  ],
  "patched_code": "resource "aws_security_group" "lb" {
  name   = "allow-all-lb"
  vpc_id = data.aws_vpc.main.id
  ingress {
    description = "Allow HTTP"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    description = "Allow HTTPS"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}",
  "fix_summary": "Replaced the overly permissive 'all traffic' ingress rule with specific rules for HTTP (port 80) and HTTPS (port 443), which are standard for load balancers. Kept the egress rule as-is since it is often required for health checks and backend communication, but added a description for clarity."
}
